for(const page of ['overview','risk','structure','graph','architecture','heatmaps','blast-radius','jordan','time-machine'])test(`${page}: real document initializes one feature against the shared snapshot`,async()=>{
 const h=await boot(page);assert.equal(h.doc.getElementById('workspace-error').hidden,true,h.doc.getElementById('workspace-error').textContent);assert.equal(h.doc.getElementById('workspace-content').hidden,false);assert.equal(h.doc.getElementById('context-repository').textContent,fixture.analysis.repository);assert.equal(h.requests.length,0);assert.equal(h.doc.getElementById('workspace-menu').listeners.get('click').length,1);assert.deepEqual(JSON.parse(JSON.stringify(h.context.activeAnalysis.summary)),fixture.analysis.summary);
 if(page==='graph'){assert(h.context.graphExplorer.adapter);assert.equal(h.context.graphExplorer.state.mode,'2d');assert.equal(h.doc.getElementById('graph-3d').disabled,true);}if(page==='heatmaps')assert.equal(h.context.architectureExplorer.state.view,'heatmap');
});
test('all direct workspaces have intentional empty states without reanalysis',async()=>{for(const page of ['overview','risk','structure','graph','architecture','heatmaps','blast-radius','jordan','time-machine']){const h=await boot(page,{data:null});assert.equal(h.doc.getElementById('workspace-content').hidden,true);assert.equal(h.doc.getElementById('workspace-empty').hidden,false);assert.equal(h.requests.length,0);}});
test('overview inventory uses actual values and filters survive page initialization',async()=>{const h=await boot('overview',{view:{'file-search':'native/','language-filter':'C','file-sort':'path'}});assert.equal(h.doc.getElementById('stat-files').textContent,String(fixture.analysis.summary.files));assert(h.doc.getElementById('file-table-body').textContent.includes('native/'));assert(!h.doc.getElementById('file-table-body').textContent.includes('README'));});
test('structure details use real source metrics and stable-ID graph navigation',async()=>{const fn=fixture.analysis.structural.functions.find(f=>f.name==='helper'),h=await boot('structure',{handoff:{page:'structure',id:fn.id}});assert(h.doc.getElementById('structure-detail').textContent.includes('Decision points'));const link=h.doc.getElementById('structure-detail').children.find(n=>n.textContent==='Inspect graph relationships');link.click();assert.equal(h.navigation.at(-1),'/workspace/graph');assert.equal(h.store.handoff().id,fn.id);});
test('graph selection crosses to impact without losing entity identity or analysis',async()=>{const fn=fixture.analysis.structural.functions.find(f=>f.name==='helper'),h=await boot('graph',{handoff:{page:'graph',id:fn.id}});assert.equal(h.context.graphExplorer.state.selected,fn.id);h.doc.getElementById('graph-inspection').children.find(n=>n.textContent==='Explore potential change impact').click();assert.equal(h.navigation.at(-1),'/workspace/blast-radius');assert.equal(h.store.handoff().id,fn.id);assert.equal(h.requests.length,0);});
test('impact evidence handoff is genuine and has cross-page graph/heatmap navigation',async()=>{const fn=fixture.analysis.structural.functions.find(f=>f.name==='helper'),h=await boot('blast-radius',{handoff:{page:'blast-radius',id:fn.id}});assert.equal(h.context.impactExplorer.origin,fn.id);assert(h.context.impactExplorer.result.records.length);h.doc.getElementById('impact-inspector').children.find(n=>n.textContent==='Open in Knowledge Graph').click();assert.equal(h.navigation.at(-1),'/workspace/graph');assert.equal(h.store.handoff().id,fn.id);});
test('architecture/heatmap handoff retains directory identity and routes to a distinct page',async()=>{const h=await boot('architecture'),component=fixture.analysis.architecture.components.find(c=>c.path==='native');h.context.architectureExplorer.selectComponent(component.id);h.doc.getElementById('ai-inspector').children.find(n=>n.textContent==='Explore directory heatmap →').click();assert.equal(h.navigation.at(-1),'/workspace/heatmaps');const handoff=h.store.handoff(),next=await boot('heatmaps',{handoff});assert.equal(next.context.architectureExplorer.state.directory,handoff.id);assert.equal(next.context.architectureExplorer.state.view,'heatmap');});
test('pagehide tears down graph renderer; history restore recreates one renderer without analysis',async()=>{const h=await boot('graph'),adapter=h.context.graphExplorer.adapter;assert(adapter);await h.emit('pagehide');assert.equal(h.context.graphExplorer.adapter,null);assert.equal(h.frames.size,0);await h.emit('pageshow',{persisted:true});assert(h.context.graphExplorer.adapter);assert.notEqual(h.context.graphExplorer.adapter,adapter);assert.equal(h.requests.length,0);});
test('changed tab snapshot invalidates stale history content',async()=>{const h=await boot('overview');await h.emit('pagehide');h.session.set('archaeologist.active','replacement');await h.emit('pageshow',{persisted:true});assert.equal(h.navigation.at(-1),'reload');});
test('storage failure is visible and does not render a false populated workspace',async()=>{const h=await boot('graph',{storageFailure:true});assert.equal(h.doc.getElementById('workspace-error').hidden,false);assert.equal(h.doc.getElementById('workspace-content').hidden,true);});
test('ZIP selection, duplicate prevention, actual upload state and successful storage/navigation',async()=>{const h=await boot('explore');h.context.selectFile(new File(['zip bytes'],'repo.zip'));assert.equal(h.doc.getElementById('analyze-zip').disabled,false);h.doc.getElementById('analyze-zip').click();h.context.analyze('zip');assert.equal(h.requests.length,1);const request=h.requests[0];assert.equal(request.url,'/api/analyze');request.upload.onprogress({lengthComputable:true,loaded:5,total:10});assert.equal(h.doc.getElementById('upload-progress').value,'50');request.upload.onload();assert.equal(h.doc.getElementById('upload-progress').getAttribute('value'),null);request.status=200;request.response=fixture.analysis;await request.onload();assert.equal(h.saved.length,1);assert.equal(h.navigation.at(-1),'/workspace/overview');});
test('GitHub URL validation and API errors remain clear and preserve prior workspace',async()=>{const h=await boot('explore');h.doc.getElementById('github-url').value='https://github.com.evil/repo/x';h.context.analyze('github');assert.equal(h.requests.length,0);assert.equal(h.doc.getElementById('error-box').hidden,false);h.doc.getElementById('github-url').value='https://github.com/owner/repo';h.context.analyze('github');const request=h.requests[0];assert.equal(request.url,'/api/analyze/github');assert.equal(JSON.parse(request.body).url,'https://github.com/owner/repo');request.status=404;request.response={error:{message:'Public repository not found.'}};await request.onload();assert(h.doc.getElementById('error-box').textContent.includes('not found'));assert.equal(h.saved.length,0);});
test('unsupported upload and empty selection do not send a request',async()=>{const h=await boot('explore');h.context.selectFile(new File(['data'],'bad.py'));assert.equal(h.doc.getElementById('analyze-zip').disabled,true);h.context.analyze('zip');assert.equal(h.requests.length,0);});

test('graph file/component navigation uses indexed stable memberships',async()=>{const fn=fixture.analysis.structural.functions.find(f=>f.name==='helper'),h=await boot('graph',{handoff:{page:'graph',id:fn.id}});const file=h.context.WorkspaceNavigation.file(fn.id),component=h.context.WorkspaceNavigation.component(fn.id);assert(file&&component);h.doc.getElementById('graph-inspection').children.find(n=>n.textContent==='Inspect component architecture').click();assert.equal(h.store.handoff().id,component);assert.equal(h.navigation.at(-1),'/workspace/architecture');h.doc.getElementById('graph-inspection').children.find(n=>n.textContent==='Explore file heatmap').click();assert.equal(h.store.handoff().id,file);assert.equal(h.navigation.at(-1),'/workspace/heatmaps');});
test('heatmap to architecture mode handoff resolves the actual directory component',async()=>{const c=fixture.analysis.architecture.components.find(c=>c.path==='native'),heat=fixture.analysis.architecture.heatmap.find(n=>n.path==='native'),h=await boot('architecture',{handoff:{page:'architecture',id:heat.id}});assert.equal(h.context.architectureExplorer.state.component,c.id);});


test('invalid replacement file clears pending input without changing the saved repository',async()=>{const h=await boot('explore');h.context.selectFile(new File(['data'],'valid.zip'));assert.equal(h.doc.getElementById('analyze-zip').disabled,false);h.context.selectFile(new File(['data'],'bad.py'));assert.equal(h.doc.getElementById('analyze-zip').disabled,true);assert.equal(h.doc.getElementById('selected-file').hidden,true);h.context.analyze('zip');assert.equal(h.requests.length,0);assert.equal(h.saved.length,0);});
test('blocked snapshot persistence offers actual unsaved JSON without false navigation',async()=>{const h=await boot('explore',{saveFailure:true});h.context.selectFile(new File(['data'],'valid.zip'));h.context.analyze('zip');const request=h.requests[0];request.status=200;request.response=fixture.analysis;await request.onload();assert.equal(h.doc.getElementById('save-unsaved').hidden,false);assert(h.doc.getElementById('error-box').textContent.includes('quota'));assert.equal(h.navigation.length,0);});
test('late visibility callbacks cannot resurrect a renderer after pagehide',async()=>{const h=await boot('graph');await h.emit('pagehide');h.context.graphExplorer.observer.fn([{isIntersecting:true}]);await new Promise(setImmediate);assert.equal(h.context.graphExplorer.adapter,null);assert.equal(h.context.graphExplorer.suspended,true);await h.emit('pageshow',{persisted:true});assert.equal(h.context.graphExplorer.suspended,false);assert(h.context.graphExplorer.adapter);});


test('navigation during snapshot restoration cannot initialize a retired graph document',async()=>{const h=await boot('graph',{delayed:true});await h.emit('pagehide');h.releaseLoad();await new Promise(setImmediate);assert.equal(h.context.graphExplorer.adapter,null);assert.equal(h.doc.getElementById('workspace-content').hidden,true);await h.emit('pageshow',{persisted:true});assert.equal(h.navigation.at(-1),'reload');});


test('saved 3D preference falls back to matching 2D state when WebGL is unavailable',async()=>{const h=await boot('graph',{view:{mode:'3d'}});assert.equal(h.context.graphExplorer.state.mode,'2d');assert.equal(h.doc.getElementById('graph-2d').getAttribute('aria-pressed'),'true');assert(h.context.graphExplorer.adapter);});
test('saved 2D preference suppresses automatic showcase 3D initialization on capable desktop',async()=>{const h=await boot('graph',{view:{mode:'2d'},desktop:true,webgl:true});assert.equal(h.context.graphExplorer.supports3D,true);assert.equal(h.context.graphExplorer.state.mode,'2d');assert(h.context.graphExplorer.adapter);assert(!h.doc.head.children.some(n=>n.attrs.src?.includes('3d-force-graph')));});


test('genuine Python-only snapshot remains useful while the risk workspace stays explicitly unscored',async()=>{const data=fixture.python_analysis;assert.equal(data.defect_risk.analyzed_functions,0);assert.equal(data.structural.summary.analyzed_functions,2);const overview=await boot('overview',{data});assert.equal(overview.doc.getElementById('stat-files').textContent,'1');assert(overview.doc.getElementById('overview-pathways').textContent.includes('Function structure'));const risk=await boot('risk',{data});assert.equal(risk.doc.getElementById('risk-analyzed').textContent,'0');assert(risk.doc.getElementById('risk-priority').textContent.includes('No scored'));assert.equal(risk.doc.getElementById('workspace-error').hidden,true);const graph=await boot('graph',{data});assert(graph.context.graphExplorer.ix.ordered.some(n=>n.type==='function'&&n.metadata.language==='Python'));});


