test('Jordan local composer retrieves actual snapshot evidence without cloud transmission',async()=>{const h=await boot('jordan');const j=h.context.jordanWorkspace;assert(j.ix.entities.size);h.doc.getElementById('jordan-question').value='Which functions are most complex?';h.doc.getElementById('jordan-form').dispatchEvent(new h.context.Event('submit'));assert(h.doc.getElementById('jordan-messages').textContent.includes('complexity'));assert(j.turns[0].response.evidence.length);assert.equal(h.cloudRequests.filter(r=>r.url.includes('explain')).length,0);assert.equal(h.requests.length,0);assert.equal(h.doc.getElementById('jordan-mode').options[1].disabled,false);assert(h.doc.getElementById('jordan-mode-status').textContent.includes('unavailable'));j.ask('Who calls it?');assert.equal(j.turns.length,2);assert.equal(h.doc.getElementById('workspace-error').hidden,true);});
test('Jordan unknown or stale handoff cannot select another entity',async()=>{const h=await boot('jordan',{handoff:{page:'jordan',id:'unknown'}});assert.equal(h.context.jordanWorkspace.entityId,null);h.context.jordanWorkspace.ask('Explain `absent`');assert(h.doc.getElementById('jordan-messages').textContent.includes('No unique'));});
test('Jordan conversation restores only for its exact snapshot; cloud turns are excluded',async()=>{const h=await boot('jordan');h.context.jordanWorkspace.ask('Summarize this repository.');await h.emit('pagehide');const state=h.store.view('jordan');assert.equal(state.turns.length,1);assert.equal(h.context.jordanWorkspace.ix,null);const other=await boot('jordan',{view:{...state,snapshot:'other'}});assert.equal(other.context.jordanWorkspace.turns.length,0);await h.emit('pageshow',{persisted:true});assert.equal(h.context.jordanWorkspace.turns.length,1);assert(h.context.jordanWorkspace.ix);});
test('Jordan new investigation clears entity and conversation without duplicate handlers',async()=>{const h=await boot('jordan');h.context.jordanWorkspace.ask('Which functions are most complex?');h.doc.getElementById('jordan-new').click();assert.equal(h.context.jordanWorkspace.turns.length,0);assert.equal(h.context.jordanWorkspace.entityId,null);assert.equal(h.doc.getElementById('jordan-welcome').hidden,false);assert.equal(h.doc.getElementById('jordan-form').listeners.get('submit').length,1);});
test('Jordan cloud mode requires review and fresh consent; withdrawal never sends',async()=>{const h=await boot('jordan',{cloudAvailable:true});const j=h.context.jordanWorkspace;h.doc.getElementById('jordan-mode').value='cloud';j.mode();j.ask('Which functions are most complex?');assert.equal(h.doc.getElementById('jordan-disclosure').hidden,false);assert.equal(h.doc.getElementById('jordan-consent').checked,false);await j.send();assert.equal(h.cloudRequests.filter(r=>r.url.endsWith('/explain')).length,0);assert(h.doc.getElementById('jordan-preview').textContent.includes('Cyclomatic complexity'));h.doc.getElementById('jordan-stay-local').click();assert.equal(j.pending,null);assert.equal(h.doc.getElementById('jordan-mode').value,'local');assert.equal(h.doc.getElementById('jordan-preview').textContent,'');});
test('Jordan cloud response renders as text, validated citations map back to real evidence, and is not persisted',async()=>{const h=await boot('jordan',{cloudAvailable:true,cloudHandler:async()=>({ok:true,json:async()=>({mode:'cloud',answer:'<img onerror=alert(1)> interpretation',citations:[{id:'E1'}],limitations:['AI-generated']})})});const j=h.context.jordanWorkspace;h.doc.getElementById('jordan-mode').value='cloud';j.ask('Which functions are most complex?');h.doc.getElementById('jordan-consent').checked=true;await j.send();assert.equal(j.turns.at(-1).mode,'cloud');assert(h.doc.getElementById('jordan-messages').textContent.includes('<img onerror'));assert.equal(h.doc.getElementById('jordan-consent').checked,false);assert.equal(j.state().turns.length,1);const sent=JSON.parse(h.cloudRequests.find(r=>r.url.endsWith('/explain')).options.body);assert.equal(sent.consent,true);assert(!('summary' in sent));assert(!('id' in sent.evidence[0]));});
test('Jordan provider failures retain a useful local answer and unknown citations are rejected',async()=>{for(const result of [{ok:false,error:'Rate limited'},{ok:true,citations:[{id:'E99'}]}]){const h=await boot('jordan',{cloudAvailable:true,cloudHandler:async()=>({ok:result.ok,json:async()=>({mode:'cloud',answer:'text',citations:result.citations,error:{message:result.error}})})});const j=h.context.jordanWorkspace;h.doc.getElementById('jordan-mode').value='cloud';j.ask('Summarize this repository.');h.doc.getElementById('jordan-consent').checked=true;await j.send();assert.equal(j.turns.length,1);assert.equal(h.doc.getElementById('jordan-error').hidden,false);}});
test('Jordan evidence buttons navigate with exact retained function identities',async()=>{const h=await boot('jordan');h.context.jordanWorkspace.ask('Which functions are most complex?');const id=h.context.jordanWorkspace.entityId;h.doc.getElementById('jordan-evidence').children.find(n=>n.textContent==='Inspect structure ↗').click();assert.equal(h.store.handoff().id,id);assert.equal(h.navigation.at(-1),'/workspace/structure');});
test('Jordan contextual launches preserve IDs and source workspace without source payload',async()=>{const fn=fixture.analysis.structural.functions.find(f=>f.name==='helper');const structure=await boot('structure',{handoff:{page:'structure',id:fn.id}});structure.doc.getElementById('structure-detail').children.find(n=>n.textContent==='Ask Jordan about this function').click();const ref=structure.store.handoff();assert.equal(ref.id,fn.id);assert.equal(ref.from,'structure');assert.equal(ref.page,'jordan');assert(JSON.stringify(ref).length<600);const jordan=await boot('jordan',{handoff:ref});assert.equal(jordan.context.jordanWorkspace.entityId,fn.id);assert.equal(jordan.doc.getElementById('jordan-return').href,'/workspace/structure');assert.equal(jordan.context.WorkspaceNavigation.askJordan('guessed'),false);});
test('impact launch preserves bounded depth, direction and exact path target',async()=>{const fn=fixture.analysis.structural.functions.find(f=>f.name==='helper'),h=await boot('blast-radius',{handoff:{page:'blast-radius',id:fn.id}});h.context.impactExplorer.pick('upstream:'+h.context.impactExplorer.result.records[0].id);h.doc.getElementById('impact-inspector').children.find(n=>n.textContent==='Ask Jordan about this impact evidence').click();const ref=h.store.handoff();assert.equal(ref.id,fn.id);assert.equal(ref.depth,1);assert.equal(ref.direction,'upstream');assert(ref.target_id);const j=await boot('jordan',{handoff:ref});j.context.jordanWorkspace.ask(j.doc.getElementById('jordan-question').value);assert.equal(j.context.jordanWorkspace.turns[0].response.intent,'impact');assert(j.doc.getElementById('jordan-messages').textContent.includes('←'));});
test('Jordan overview, graph and architecture entry points are functional',async()=>{const graph=await boot('graph');const fn=fixture.analysis.structural.functions[0];graph.context.graphExplorer.choose(fn.id);graph.doc.getElementById('graph-inspection').children.find(n=>n.textContent==='Ask Jordan about these relationships').click();assert.equal(graph.store.handoff().id,fn.id);const c=fixture.analysis.architecture.components[0],a=await boot('architecture');a.context.architectureExplorer.selectComponent(c.id);a.doc.getElementById('ai-inspector').children.find(n=>n.textContent==='Ask Jordan about this component / file').click();assert.equal(a.store.handoff().id,c.id);const overview=await boot('overview');assert(overview.doc.getElementById('overview-pathways').textContent.includes('Jordan engineering'));});
test('Jordan cancellation and repository teardown reject late provider responses',async()=>{let resolve;const gate=new Promise(r=>resolve=r);const h=await boot('jordan',{cloudAvailable:true,cloudHandler:()=>gate});const j=h.context.jordanWorkspace;h.doc.getElementById('jordan-mode').value='cloud';j.ask('Summarize this repository.');h.doc.getElementById('jordan-consent').checked=true;const request=j.send();const signal=h.cloudRequests.find(r=>r.url.endsWith('/explain')).options.signal;await h.emit('pagehide');assert(signal.aborted);resolve({ok:true,json:async()=>({mode:'cloud',answer:'stale repository answer',citations:[]})});await request;assert.equal(j.turns.length,1);assert.equal(j.ix,null);assert(!h.doc.getElementById('jordan-messages').textContent.includes('stale repository answer'));});
test('Jordan unchecking consent cancels in-flight work and clears disclosure',async()=>{let resolve;const gate=new Promise(r=>resolve=r);const h=await boot('jordan',{cloudAvailable:true,cloudHandler:()=>gate});const j=h.context.jordanWorkspace;h.doc.getElementById('jordan-mode').value='cloud';j.ask('Summarize this repository.');h.doc.getElementById('jordan-consent').checked=true;const task=j.send();h.doc.getElementById('jordan-consent').checked=false;h.doc.getElementById('jordan-consent').dispatchEvent(new h.context.Event('change'));assert.equal(j.pending,null);assert.equal(h.doc.getElementById('jordan-mode').value,'local');resolve({ok:true,json:async()=>({mode:'cloud',answer:'late',citations:[]})});await task;assert.equal(j.turns.length,1);});
test('Jordan works for Python-only and empty repositories without model claims',async()=>{const python=await boot('jordan',{data:fixture.python_analysis});python.context.jordanWorkspace.ask('Which functions have highest risk?');assert(python.doc.getElementById('jordan-messages').textContent.includes('No genuine C-function scores'));const empty={...fixture.python_analysis,repository:'empty',summary:{files:0,directories:0,total_lines:0},knowledge_graph:{nodes:[],edges:[],references:[],coverage:{complete:true}},structural:{functions:[],hotspots:[],summary:{analyzed_functions:0}},architecture:{components:[],edges:[]}};const h=await boot('jordan',{data:empty});h.context.jordanWorkspace.ask('Summarize this repository.');assert(h.doc.getElementById('jordan-messages').textContent.includes('0 inventoried files'));});

function selectEnhanced(h){const select=h.doc.getElementById('jordan-mode');assert.equal(select.options[1].disabled,false);select.value='cloud';select.dispatchEvent(new h.context.Event('change'));}
test('Enhanced Mode selection when configured changes the actual control and requires fresh consent',async()=>{const h=await boot('jordan',{cloudAvailable:true});selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'cloud');assert(h.doc.getElementById('jordan-mode-label').textContent.includes('AI-enhanced'));assert(h.doc.getElementById('jordan-mode-status').textContent.includes('connectivity is not verified'));h.context.jordanWorkspace.ask('Summarize this repository.');assert.equal(h.doc.getElementById('jordan-disclosure').hidden,false);assert.equal(h.doc.getElementById('jordan-consent').checked,false);await h.context.jordanWorkspace.send();assert.equal(h.cloudRequests.filter(r=>r.url.endsWith('/explain')).length,0);});
test('Enhanced Mode unconfigured selection explains exact setup without enabling cloud',async()=>{const h=await boot('jordan',{capabilityHandler:async()=>({ok:true,json:async()=>({cloud_available:false,configuration_issues:['cloud_disabled','missing_key','missing_model']})})});selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'local');assert.equal(h.context.jordanWorkspace.cloud,false);const help=h.doc.getElementById('jordan-mode-status');assert.equal(help.getAttribute('role'),'status');assert.equal(h.doc.getElementById('jordan-mode').getAttribute('aria-describedby'),help.id);assert(help.textContent.includes('JORDAN_CLOUD_ENABLED'));assert(help.textContent.includes('JORDAN_OPENAI_API_KEY'));assert(help.textContent.includes('JORDAN_OPENAI_MODEL'));h.context.jordanWorkspace.ask('Summarize this repository.');assert.equal(h.doc.getElementById('jordan-disclosure').hidden,true);assert.equal(h.cloudRequests.filter(r=>r.url.endsWith('/explain')).length,0);});
for(const [name,handler]of [['network unavailable',async()=>{throw Error('private backend details');}],['backend error',async()=>({ok:false,status:500,json:async()=>({error:{message:'secret backend details'}})})],['invalid capability response',async()=>({ok:true,json:async()=>({cloud_available:'true'})})]])test('Enhanced Mode '+name+' explains failed check, keeps local and does not echo raw errors',async()=>{const h=await boot('jordan',{capabilityHandler:handler});selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'local');assert.equal(h.context.jordanWorkspace.capabilityState,'error');assert(h.doc.getElementById('jordan-mode-status').textContent.includes('could not be checked'));assert(!h.doc.getElementById('jordan-mode-status').textContent.includes('backend details'));assert.equal(h.cloudRequests.filter(r=>r.url.endsWith('/explain')).length,0);});
test('explicit capability recheck recovers configuration and revokes stale available state on failure',async()=>{let state='unconfigured';const h=await boot('jordan',{capabilityHandler:async()=>{if(state==='error')throw Error('offline');return {ok:true,json:async()=>({cloud_available:state==='configured'})};}});selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'local');state='configured';h.doc.getElementById('jordan-mode-recheck').click();await new Promise(setImmediate);selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'cloud');state='error';h.doc.getElementById('jordan-mode-recheck').click();await new Promise(setImmediate);assert.equal(h.context.jordanWorkspace.cloud,false);selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'local');});
test('selecting Enhanced during capability loading does not abort discovery; old recheck responses cannot overwrite new state',async()=>{let resolve,stale,calls=0;const gate=new Promise(r=>resolve=r),old=new Promise(r=>stale=r);const h=await boot('jordan',{capabilityHandler:async()=>{calls++;if(calls===1)return gate;if(calls===2)return old;return {ok:true,json:async()=>({cloud_available:true})};}});selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'local');assert.equal(h.cloudRequests[0].options.signal.aborted,false);resolve({ok:true,json:async()=>({cloud_available:true})});await new Promise(setImmediate);assert.equal(h.context.jordanWorkspace.cloud,true);selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'cloud');h.doc.getElementById('jordan-mode-recheck').click();h.doc.getElementById('jordan-mode-recheck').click();await new Promise(setImmediate);assert.equal(h.context.jordanWorkspace.cloud,true);stale({ok:true,json:async()=>({cloud_available:false})});await new Promise(setImmediate);assert.equal(h.context.jordanWorkspace.cloud,true);assert(h.doc.getElementById('jordan-mode-status').textContent.includes('available for selection'));});

test('capability timeout has an actionable error and never enables Enhanced Mode',async()=>{const h=await boot('jordan',{capabilityHandler:async(url,{signal})=>new Promise((resolve,reject)=>signal.addEventListener('abort',()=>reject(Error('aborted'))))});h.timers.values().next().value();await new Promise(setImmediate);assert.equal(h.context.jordanWorkspace.capabilityState,'error');selectEnhanced(h);assert.equal(h.doc.getElementById('jordan-mode').value,'local');assert(h.doc.getElementById('jordan-mode-status').textContent.includes('timed out'));assert.equal(h.context.jordanWorkspace.cloud,false);});

test('ZIP Time Machine has no invented history or network requests',async()=>{const h=await boot('time-machine');assert.equal(h.doc.getElementById('tm-empty').hidden,false);assert.equal(h.doc.getElementById('tm-load').disabled,true);assert.equal(h.doc.getElementById('tm-results').hidden,true);assert.equal(h.cloudRequests.length,0);});
test('genuine Git fixture history is fetched once and persisted under the same workspace',async()=>{const data=structuredClone(fixture.history_analysis),h=await boot('time-machine',{data,historyHandler:async()=>({ok:true,json:async()=>fixture.history})});h.doc.getElementById('tm-load').click();await new Promise(setImmediate);await new Promise(setImmediate);assert.equal(h.context.timeMachine.history.commits.length,7);assert.equal(h.doc.getElementById('tm-results').hidden,false);assert.equal(h.saved.length,1);assert.equal(h.requests.length,0);assert.equal(h.context.timeMachine.history.anchor,data.source.snapshot_commit);const restored=await boot('time-machine',{data});assert.equal(restored.context.timeMachine.history.commits.length,7);assert.equal(restored.cloudRequests.length,0);});
test('history timeline selection preserves SVG geometry and zoom; panning and fit work',async()=>{const data={...structuredClone(fixture.history_analysis),history:fixture.history},h=await boot('time-machine',{data}),t=h.context.timeMachine.timeline;const svg=t.canvas;t.zoom(.5);const before=t.viewport.w;t.select(fixture.history.commits.at(-1).sha);assert.equal(t.canvas,svg);assert.equal(t.viewport.w,before);t.canvas.dispatchEvent({type:'pointerdown',target:t.canvas,clientX:500,pointerId:1});t.canvas.dispatchEvent({type:'pointermove',clientX:550});assert.notEqual(t.viewport.x,0);t.controls.children.find(n=>n.textContent==='Fit History').click();assert.equal(t.viewport.w,t.world);assert.equal(t.viewport.x,0);await h.emit('pagehide');assert.equal(h.context.timeMachine.timeline,null);});
test('history activity contains actual dates and month selection applies UTC filters',async()=>{const h=await boot('time-machine',{data:{...structuredClone(fixture.history_analysis),history:fixture.history}});const t=h.context.timeMachine.timeline;assert(t.activity.textContent.includes('2025-01'));t.range('2025-01');assert.equal(h.doc.getElementById('tm-from').value,'2025-01-01');assert.equal(h.doc.getElementById('tm-to').value,'2025-01-31');assert.equal(h.context.timeMachine.filtered().length,7);});
test('churn map metric, directory drilldown and literal file inspection use actual Git changes',async()=>{const h=await boot('time-machine',{data:{...structuredClone(fixture.history_analysis),history:fixture.history}});h.doc.getElementById('tm-tab-churn').click();assert(h.context.timeMachine.map.canvas);const metric=h.doc.getElementById('tm-metric');metric.value='churn';metric.dispatchEvent(new h.context.Event('change'));assert.equal(h.context.timeMachine.metric,'churn');h.context.timeMachine.inspectFile('binary.dat');assert(h.doc.getElementById('tm-inspection').textContent.includes('Unavailable'));assert.equal(h.cloudRequests.length,0);});
test('comparison studio sends exact revisions and shows real bounded evidence safely',async()=>{const h=await boot('time-machine',{data:{...structuredClone(fixture.history_analysis),history:fixture.history},historyHandler:async()=>({ok:true,json:async()=>fixture.history_pair})});h.doc.getElementById('tm-tab-compare').click();h.context.timeMachine.base=fixture.history_pair.base;h.context.timeMachine.head=fixture.history_pair.head;h.context.timeMachine.render();h.doc.getElementById('tm-compare').click();await new Promise(setImmediate);assert.equal(h.context.timeMachine.comparison.files.length,fixture.history_pair.files.length);assert(h.doc.getElementById('tm-view').textContent.includes('measured additions'));assert(h.doc.getElementById('tm-inspection').textContent.includes('REVISION COMPARISON'));assert.equal(h.requests.length,0);const sent=JSON.parse(h.cloudRequests[0].options.body);assert.equal(sent.base,fixture.history_pair.base);assert.equal(sent.head,fixture.history_pair.head);assert(!JSON.stringify(h.saved).includes('@@'));});
test('evolution retrieves an exact Git tree, scrubs actual revisions and persists metadata only',async()=>{const data={...structuredClone(fixture.history_analysis),history:structuredClone(fixture.history)},h=await boot('time-machine',{data,historyHandler:async(url,options)=>{const body=JSON.parse(options.body);return {ok:true,json:async()=>fixture.history_trees[body.revision]};}});h.doc.getElementById('tm-tab-evolution').click();assert(h.doc.getElementById('tm-view').textContent.includes('No historical state is inferred'));h.doc.getElementById('tm-tree-load').click();await new Promise(setImmediate);await new Promise(setImmediate);assert(h.context.timeMachine.map.canvas);assert.equal(h.context.timeMachine.trees.size,1);assert.equal(h.saved.at(-1).revision_trees.length,1);const scrub=h.doc.getElementById('tm-scrub');scrub.value='0';scrub.dispatchEvent(new h.context.Event('input'));assert.equal(h.context.timeMachine.selected,h.context.TimeMachineData.chronology(fixture.history.commits)[0].sha);assert.equal(h.requests.length,0);});
test('evolution playback visits cached genuine revisions only and cleans up on exit',async()=>{const history={...structuredClone(fixture.history),revision_trees:Object.values(fixture.history_trees).slice(0,3)},h=await boot('time-machine',{data:{...structuredClone(fixture.history_analysis),history}});h.doc.getElementById('tm-tab-evolution').click();h.context.timeMachine.togglePlayback();assert.equal(h.context.timeMachine.playing,true);const timer=h.context.timeMachine.playTimer;h.timers.get(timer)();assert(h.context.timeMachine.trees.has(h.context.timeMachine.selected));h.doc.getElementById('tm-tab-timeline').click();assert.equal(h.context.timeMachine.playing,false);assert.equal(h.context.timeMachine.playTimer,null);await h.emit('pagehide');assert.equal(h.context.timeMachine.map,null);});

test('evolution reduced motion disables playback without disabling real revision scrubbing',async()=>{const history={...structuredClone(fixture.history),revision_trees:Object.values(fixture.history_trees).slice(0,2)},h=await boot('time-machine',{reducedMotion:true,data:{...structuredClone(fixture.history_analysis),history}});h.doc.getElementById('tm-tab-evolution').click();assert.equal(h.doc.getElementById('tm-play').disabled,true);h.context.timeMachine.togglePlayback();assert(!h.context.timeMachine.playing);assert(h.doc.getElementById('tm-scrub'));});
test('current structure and graph handoffs use exact file IDs and historical path evidence',async()=>{const data={...structuredClone(fixture.history_analysis),history:fixture.history},fn=data.structural.functions.find(f=>f.name==='helper'),h=await boot('structure',{data,handoff:{page:'structure',id:fn.id}});h.doc.getElementById('structure-detail').children.find(n=>n.textContent==='Explore file history').click();const handoff=h.store.handoff();assert.equal(handoff.id,fn.file_id);assert.equal(handoff.page,'time-machine');const t=await boot('time-machine',{data,handoff});assert.equal(t.context.timeMachine.fileScope,fn.path);assert(t.context.timeMachine.filtered().every(c=>c.files.some(f=>f.path===fn.path||f.previous_path===fn.path)));const g=await boot('graph',{data});g.context.graphExplorer.choose(fn.file_id);g.doc.getElementById('graph-inspection').children.find(n=>n.textContent==='Explore file history').click();assert.equal(g.store.handoff().id,fn.file_id);});
test('history cancellation preserves evidence and cannot restore a retired renderer',async()=>{let resolve;const pending=new Promise(r=>resolve=r),h=await boot('time-machine',{data:{...structuredClone(fixture.history_analysis),history:fixture.history},historyHandler:()=>pending});h.doc.getElementById('tm-load').click();const signal=h.cloudRequests[0].options.signal;h.doc.getElementById('tm-cancel').click();assert(signal.aborted);assert(h.doc.getElementById('tm-status').textContent.includes('cancelled'));await h.emit('pagehide');resolve({ok:true,json:async()=>fixture.history});await new Promise(setImmediate);h.context.timeMachine.render();assert.equal(h.context.timeMachine.timeline,null);assert.equal(h.saved.length,0);});
