// Task 6B.1: actual document controls and genuine fixture evidence; no visual claims.
const historyData=()=>({...structuredClone(fixture.history_analysis),history:structuredClone(fixture.history)});
const historyOK=(value,api=null)=>({ok:true,headers:{get:()=>api?JSON.stringify(api):null},json:async()=>value});
test('identical in-flight history resource requests share one fetch without canceling each other',async()=>{let resolve;const pending=new Promise(r=>resolve=r),h=await boot('time-machine',{data:historyData(),historyHandler:()=>pending}),m=h.context.timeMachine,revision=fixture.history.commits[0].sha;const a=m.request('tree',{revision}),b=m.request('tree',{revision});assert.equal(h.cloudRequests.length,1);assert.equal(h.cloudRequests[0].options.signal.aborted,false);resolve(historyOK(fixture.history_trees[revision]));assert.equal(await a,await b);assert.equal(m.requestController,null);});
test('repeated loaded tree selection and harmless renders make no extra HTTP requests',async()=>{const h=await boot('time-machine',{data:historyData(),historyHandler:async(u,o)=>historyOK(fixture.history_trees[JSON.parse(o.body).revision])}),m=h.context.timeMachine;m.view='evolution';m.render();const sha=m.selected;await h.context.TimeMachineEvolution.retrieve(m,sha);await h.context.TimeMachineEvolution.retrieve(m,sha);for(let i=0;i<5;i++)m.render();assert.equal(h.cloudRequests.length,1);assert(h.doc.getElementById('tm-api-status').textContent.includes('cached'));assert.equal(m.trees.get(sha).revision,sha);});
test('identical comparisons coalesce then reuse bounded memory results and never persist patches',async()=>{let resolve;const pending=new Promise(r=>resolve=r),h=await boot('time-machine',{data:historyData(),historyHandler:()=>pending}),m=h.context.timeMachine;m.base=fixture.history_pair.base;m.head=fixture.history_pair.head;const a=m.compare(),b=m.compare();assert.equal(h.cloudRequests.length,1);resolve(historyOK(fixture.history_pair));await Promise.all([a,b]);await m.compare();assert.equal(h.cloudRequests.length,1);assert.equal(m.comparisons.size,1);assert.equal(m.comparison.base,m.base);assert(!JSON.stringify(h.saved).includes('@@'));await h.emit('pagehide');assert.equal(m.comparisons.size,0);});
test('failed new comparison preserves previous successful comparison and history',async()=>{let calls=0;const h=await boot('time-machine',{data:historyData(),historyHandler:async()=>++calls===1?historyOK(fixture.history_pair):{ok:false,json:async()=>({error:{message:'GitHub denied access to this repository.'}})}}),m=h.context.timeMachine;m.base=fixture.history_pair.base;m.head=fixture.history_pair.head;await m.compare();const prior=m.comparison;m.base=fixture.history.commits.find(c=>c.sha!==m.base&&c.sha!==m.head).sha;await m.compare();assert.equal(m.comparison,prior);assert.equal(m.history.commits.length,7);assert(h.doc.getElementById('tm-error').textContent.includes('denied access'));assert.equal(h.doc.getElementById('tm-retry').hidden,false);});
test('primary quota reset is displayed from actual metadata and cooldown prevents new network work',async()=>{const until=Math.floor(Date.now()/1000)+90,api={state:'limited',kind:'primary',remaining:0,reset_at:until,retry_at:until,cooldown_source:'reported'},h=await boot('time-machine',{data:historyData(),historyHandler:async()=>({ok:false,json:async()=>({error:{message:'GitHub primary allowance is limited.',api}})})}),m=h.context.timeMachine;await m.load();assert(h.doc.getElementById('tm-api-status').textContent.includes('reported reset'));assert(h.doc.getElementById('tm-api-status').textContent.includes('0 requests'));assert.equal(h.doc.getElementById('tm-retry').hidden,false);h.doc.getElementById('tm-retry').click();await m.request('tree',{revision:m.selected});assert.equal(h.cloudRequests.length,1);assert(h.doc.getElementById('tm-error').textContent.includes('cooldown'));m.trees.set(m.selected,fixture.history_trees[m.selected]);assert(await m.request('tree',{revision:m.selected}));assert.equal(h.cloudRequests.length,1);assert(h.doc.getElementById('tm-api-status').textContent.includes('limited'));});
test('secondary backoff does not invent a reset timestamp and retry remains explicit',async()=>{let calls=0;const api={state:'limited',kind:'secondary',retry_at:Math.floor(Date.now()/1000)+60,cooldown_source:'conservative_backoff'},h=await boot('time-machine',{data:historyData(),historyHandler:async()=>++calls===1?{ok:false,json:async()=>({error:{message:'GitHub temporarily restricts request activity.',api}})}:historyOK(fixture.history,{state:'connected',remaining:40,cache:'hit'})}),m=h.context.timeMachine;await m.load();assert(!h.doc.getElementById('tm-api-status').textContent.includes('reported reset'));assert(h.doc.getElementById('tm-api-status').textContent.includes('conservative'));m.cooldownUntil=Date.now()-1;assert.equal(h.cloudRequests.length,1);h.doc.getElementById('tm-retry').click();await new Promise(setImmediate);await new Promise(setImmediate);assert.equal(h.cloudRequests.length,2);assert(h.doc.getElementById('tm-api-status').textContent.includes('connected'));});
test('rapid revision switching aborts stale browser consumer and rejects late tree responses',async()=>{const waiting=[],h=await boot('time-machine',{data:historyData(),historyHandler:()=>new Promise(resolve=>waiting.push(resolve))}),m=h.context.timeMachine,shas=fixture.history.commits.slice(0,2).map(c=>c.sha);m.view='evolution';m.selected=shas[0];const first=h.context.TimeMachineEvolution.retrieve(m,shas[0]);m.selected=shas[1];const second=h.context.TimeMachineEvolution.retrieve(m,shas[1]);assert(h.cloudRequests[0].options.signal.aborted);waiting[1](historyOK(fixture.history_trees[shas[1]]));await second;waiting[0](historyOK(fixture.history_trees[shas[0]]));await first;assert.equal(m.trees.size,1);assert(m.trees.has(shas[1]));assert.equal(m.selected,shas[1]);});
test('comparison cache expires and evicts without adding source to snapshot or mixing repositories',async()=>{const h=await boot('time-machine',{data:historyData()}),m=h.context.timeMachine;for(const c of fixture.history.commits.slice(0,4))m.rememberComparison({...fixture.history_pair,base:c.sha});assert.equal(m.comparisons.size,3);const [key,row]=m.comparisons.entries().next().value;row.expires=Date.now()-1;assert.equal(m.cachedComparison(row.value.base,row.value.head),null);assert.equal(m.comparisons.size,2);m.initialize(historyData(),h.store,null,null);assert.equal(m.comparisons.size,0);assert(!JSON.stringify(m.state()).includes('patch'));assert.equal(h.cloudRequests.length,0);});
test('server cache status is visible without an extra status endpoint or rerender fetch',async()=>{const h=await boot('time-machine',{data:historyData(),historyHandler:async()=>historyOK(fixture.history,{state:'connected',remaining:17,reset_at:2000000000,cache:'hit'})}),m=h.context.timeMachine;await m.load();const status=h.doc.getElementById('tm-api-status').textContent;assert(status.includes('cached')&&status.includes('17 requests'));m.render();m.render();assert.equal(h.cloudRequests.length,1);assert.equal(h.doc.getElementById('tm-api-status').getAttribute('role'),'status');});
test('smaller partial history never discards a previously loaded larger pinned window',async()=>{const partial={...fixture.history,commits:fixture.history.commits.slice(0,2)},h=await boot('time-machine',{data:historyData(),historyHandler:async()=>historyOK(partial,{state:'limited',cache:'mixed'})}),m=h.context.timeMachine;await m.load();assert.equal(m.history.commits.length,7);assert(h.doc.getElementById('tm-error').textContent.includes('larger window'));});
